SELECT NVL(t2.PBC_CODE, report.PBC_PROD_ID) AS pbcProdId, report.LOAN_BASIS_ID AS loanBasisId, report.STATUS AS status, report.DETAILUUID AS detailuuid, report.TERMID AS termid, report.ASSET_CODE AS assetCode, report.LOAN_TRANSFEROR_ID AS loanTransferorId, report.LOAN_CONTRACT_ORG_ID AS loanContractOrgId, report.LOAN_CONTRACT_ORG_CODE AS loanContractOrgCode, report.BORROWER_TYPE AS borrowerType, report.BORROWER_COUNTY AS borrowerCounty, report.BORROWER_ID AS borrowerId, report.INDUSTRY_INFO AS industryInfo, report.ENTERPRISE_INVESTOR_TYPE AS enterpriseInvestorType, report.ENTERPRISE_SCALE AS enterpriseScale, report.LOAN_PRD_TYPE AS loanPrdType, report.LOAN_ACTUAL_INVEST AS loanActualInvest, report.LOAN_VDATE AS loanVdate, report.LOAN_MDATE AS loanMdate, report.LOAN_EXTENSION_DUE_DATE AS loanExtensionDueDate, report.RATE_FIXED AS rateFixed, report.RATE_LEVEL AS rateLevel, report.LOANS_TYPE AS loansType, report.LOAN_GUARANTEE_MODE AS loanGuaranteeMode, report.LOAN_QUALITY AS loanQuality, report.LOAN_STATE AS loanState, report.LOAN_TRANSFEROR_RATE AS loanTransferorRate, report.ORIG_CCY AS origCcy, report.ORIG_CONTRACT_AMOUNT AS origContractAmount, report.ORIG_CONTRACT_AMOUNT_CNY AS origContractAmountCny, report.AMT_CCY AS amtCcy, report.CONTRACT_AMOUNT AS contractAmount, report.CONTRACT_AMOUNT_CNY AS contractAmountCny, report.SUBMIT_TIME AS submitTime, report.PBC_SUBMIT_DEADLINE AS pbcSubmitDeadline, report.SUBMIT_DEADLINE AS submitDeadline, report.SEND_STATUS AS sendStatus, report.STATUS_DATE AS statusDate, report.PROD_ID AS prodId FROM PBC_COL_LOAN_DETAIL_SUB report LEFT JOIN( SELECT INSIDE_PROD_ID, PBC_CODE FROM PBC_PROD_ASSETPOOL_CODE WHERE STATUS = 'E' AND CODE_TYPE = '01') t2 ON t2.INSIDE_PROD_ID = report.PROD_ID
report.SEND_STATUS ='01'
and NAL(t2.PBC_CODE, report.PBC_PROD_ID) = #{pbcProdId,jdbcType=VARCHAR}
AND report.ASSET_CODE = #{assetCode,jdbcType=VARCHAR}
AND report.LOANS_TYPE = #{loansType,jdbcType=VARCHAR}
AND report.TERMID = #{termid,jdbcType=VARCHAR}
AND report.SEND_STATUS = #{sendStatus,jdbcType=VARCHAR}
AND TO_CHAR(report.SUBMIT_TIME, 'yyyy-MM-dd') >= #{submitTimeStart,jdbcType=VARCHAR}
AND TO_CHAR(report.SUBMIT_TIME, 'yyyy-MM-dd') <= #{submitTimeEnd,jdbcType=VARCHAR}
AND TO_CHAR(report.SUBMIT_DEADLINE, 'yyyy-MM-dd') >= #{pbcSubmitDeadlineStart,jdbcType=VARCHAR}
AND TO_CHAR(report.SUBMIT_DEADLINE, 'yyyy-MM-dd') <= #{pbcSubmitDeadlineEnd,jdbcType=VARCHAR}
AND TO_CHAR(report.STATUS_DATE, 'yyyy-MM-dd') >= #{statusDateStart,jdbcType=VARCHAR}
AND TO_CHAR(report.STATUS_DATE, 'yyyy-MM-dd') <= #{statusDateEnd,jdbcType=VARCHAR}
ORDER BY report.TERMID, report.PBC_PROD_ID, report.ASSET_CODE, report.LOANS_TYPE,report.SUBMIT_DEADLINE ASC, report.UPDATE_TIME DESC
